        let handle = std::thread::spawn(move || {
            tx1.send(gettid())
                .expect("perf test operation should succeed");
            rx2.recv().expect("perf test operation should succeed");
            do_branches(ITERS);
        });

        let pc = Builder::new(
            rx1.recv()
                .expect("perf test operation should succeed")
                .as_raw(),
