            Event::Signal(Signal::SIGTRAP) => {
                let expected_rip = saved_regs
                    .ip()
                    .checked_add(cp::SYSCALL_INSTR_SIZE as u64)
                    .ok_or(Errno::EOVERFLOW)?;
