async fn liteinst_arch_prctl<S: SyscallInfo>(
    &mut self,
    task: Stopped,
    syscall: S,
) -> (Stopped, Result<Result<i64, Errno>, TraceError>) {
    let (nr, args) = syscall.into_parts();
