1	diff --git a/reverie-ptrace/src/clock_origin_tests.rs b/reverie-ptrace/src/clock_origin_tests.rs
2	new file mode 100644
3	--- /dev/null
4	+++ b/reverie-ptrace/src/clock_origin_tests.rs
5	@@ -0,0 +1,399 @@
6	+/*
7	+ * Copyright (c) Meta Platforms, Inc. and affiliates.
8	+ *
9	+ * This source code is licensed under the BSD-style license found in the
10	+ * LICENSE file in the root directory of this source tree.
11	+ */
12	+
13	+use std::os::unix::fs::PermissionsExt;
14	+use std::sync::Mutex;
15	+use std::sync::atomic::AtomicU64;
16	+use std::sync::atomic::Ordering;
17	+
18	+use reverie::Guest;
19	+use reverie::TimerSchedule;
20	+use reverie::syscalls::Exit;
21	+use reverie::syscalls::Getpid;
22	+use reverie::syscalls::Syscall;
23	+use reverie::syscalls::SyscallInfo;
24	+use serde::Deserialize;
25	+use serde::Serialize;
26	+
27	+use super::*;
28	+
29	+#[derive(Clone, Debug, Default, Deserialize, Serialize)]
30	+struct Config {
31	+    injected_exec: bool,
32	+    startup_request: u8,
33	+    post_exec_request: bool,
34	+    initial_failure: bool,
35	+}
36	+
37	+#[derive(Debug, Deserialize, Serialize)]
38	+enum Observation {
39	+    Start(u64),
40	+    ExecCall(u64),
41	+    PostExec(u64),
42	+    Timer(u64),
43	+    Boundary(u64),
44	+    FailedExec(u64),
45	+}
46	+
47	+#[derive(Default)]
48	+struct ClockLog(Mutex<Vec<Observation>>);
49	+
50	+#[reverie::global_tool]
51	+impl GlobalTool for ClockLog {
52	+    type Config = Config;
53	+    type Request = Observation;
54	+    type Response = ();
55	+
56	+    async fn receive_rpc(&self, _from: Pid, observation: Observation) {
57	+        self.0.lock().unwrap().push(observation);
58	+    }
59	+}
60	+
61	+#[derive(Default)]
62	+struct ClockTool;
63	+
64	+fn request_startup_timer<G: Guest<ClockTool>>(guest: &mut G, kind: u8) {
65	+    match kind {
66	+        0 => {}
67	+        1 => guest.set_timer_precise(TimerSchedule::Rcbs(1)).unwrap(),
68	+        2 => guest.set_timer(TimerSchedule::Rcbs(1)).unwrap(),
69	+        3 => guest
70	+            .set_timer_precise(TimerSchedule::RcbsAndInstructions(1, 2))
71	+            .unwrap(),
72	+        _ => panic!("unknown control timer kind"),
73	+    }
74	+}
75	+
76	+#[reverie::tool]
77	+impl Tool for ClockTool {
78	+    type GlobalState = ClockLog;
79	+    type ThreadState = bool;
80	+
81	+    fn subscriptions(config: &Config) -> Subscription {
82	+        let mut events = Subscription::none();
83	+        events.syscalls([Sysno::getpid]);
84	+        if config.injected_exec {
85	+            events.syscalls([Sysno::execve]);
86	+        }
87	+        events
88	+    }
89	+
90	+    async fn handle_thread_start<G: Guest<Self>>(&self, guest: &mut G) -> Result<(), Error> {
91	+        assert!(guest.is_command_bootstrap());
92	+        let clock = guest.read_clock()?;
93	+        eprintln!("CLOCK_ORIGIN_TEST start={clock}");
94	+        assert_eq!(clock, 0);
95	+        guest.send_rpc(Observation::Start(clock)).await;
96	+        let kind = guest.config().startup_request;
97	+        request_startup_timer(guest, kind);
98	+        Ok(())
99	+    }
100	+
101	+    async fn handle_syscall_event<G: Guest<Self>>(
102	+        &self,
103	+        guest: &mut G,
104	+        call: Syscall,
105	+    ) -> Result<i64, Error> {
106	+        if call.number() == Sysno::execve {
107	+            assert!(guest.is_command_bootstrap());
108	+            let clock = guest.read_clock()?;
109	+            eprintln!("CLOCK_ORIGIN_TEST intercepted_exec={clock}");
110	+            assert_eq!(clock, 0, "the command launcher is outside guest accounting");
111	+            guest.send_rpc(Observation::ExecCall(clock)).await;
112	+            // This request is newer than handle_thread_start and exercises
113	+            // the injected route's missing ordinary observe_event call.
114	+            let kind = guest.config().startup_request;
115	+            request_startup_timer(guest, kind);
116	+            if guest.config().initial_failure {
117	+                assert_eq!(guest.inject(call).await, Err(Errno::ENOENT));
118	+                assert!(guest.is_command_bootstrap());
119	+                assert!(!*guest.thread_state());
120	+                let clock = guest.read_clock()?;
121	+                eprintln!("CLOCK_ORIGIN_TEST failed_exec={clock}");
122	+                assert_eq!(clock, 0, "failed initial exec did not activate the clock");
123	+                guest.send_rpc(Observation::FailedExec(clock)).await;
124	+                guest.tail_inject(Exit::default().with_status(27)).await
125	+            }
126	+            guest.tail_inject(call).await
127	+        } else {
