#[derive(Clone, Copy, Debug, Default, Deserialize, Eq, PartialEq, Serialize)]
enum Mode {
    #[default]
    PostExec,
    Replace,
    SameThenPrivate,
    TailSame,
    TailOther,
    PostExecTail,
    Emulate,
    EmulateErrno,
}

impl Mode {
    fn emulates(self) -> bool {
        matches!(self, Self::Emulate | Self::EmulateErrno)
    }
}

#[derive(Clone, Debug, Default, Deserialize, Serialize)]
struct Config {
    mode: Mode,
    timestamp_rip: u64,
}

#[derive(Debug, Deserialize, Eq, PartialEq, Serialize)]
enum Observation {
    PostExec,
    Write,
    Emulated,
    Timestamp,
    Boundary(u64),
}

#[derive(Default)]
struct Log(Mutex<Vec<Observation>>);

#[reverie::global_tool]
impl GlobalTool for Log {
    type Config = Config;
    type Request = Observation;
    type Response = ();

    async fn receive_rpc(&self, _from: Pid, observation: Observation) {
        self.0.lock().unwrap().push(observation);
    }
}

#[derive(Default)]
struct StopTool;

fn word<G: Guest<StopTool>>(guest: &G, address: usize) -> u64 {
    guest
        .memory()
        .read_value(Addr::<u64>::from_raw(address).unwrap())
        .unwrap()
}

fn replacement() -> WriteCall {
    WriteCall::default()
        .with_fd(1)
        .with_buf(Addr::from_raw(REPLACEMENT))
        .with_len(1)
}

